sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({api, helpers}) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const rows = id => ((api.data[id] || {}).results) || [];
  const v = (r, f) => (r[f] && r[f].value) || '';
  const dv = (r, f) => (r[f] && (r[f].displayValue || r[f].value)) || '';
  const head = t => '<div style="font-size:16px;color:#2e3d49;padding-bottom:12px;margin-bottom:8px;border-bottom:1px solid #e3e7ea">' + esc(t) + '</div>';
  const bars = (items, fmt) => {
    const max = Math.max(1, ...items.map(i => i.n));
    return '<table style="width:100%;border-collapse:collapse">' + items.map(i =>
      '<tr><td style="width:160px;padding:7px 8px 7px 0;color:#4a5a66;font-size:14px">' + esc(i.l) + '</td>' +
      '<td style="padding:7px 0"><div style="height:18px;border-radius:2px;background:' + i.c + ';width:' + Math.max(i.n ? 2 : 0, Math.round(i.n / max * 100)) + '%"></div></td>' +
      '<td style="width:90px;padding:7px 0 7px 10px;text-align:right;color:#1d2b36;font-size:14px">' + esc(fmt ? fmt(i.n) : i.n) + '</td></tr>').join('') + '</table>';
  };
  const list = (items, empty) => items.length ? items.map((i, k) =>
      '<div style="display:flex;justify-content:space-between;gap:12px;padding:9px 0;font-size:14px;' + (k < items.length - 1 ? 'border-bottom:1px solid #eef1f3' : '') + '">' +
      (i.href ? '<a href="' + i.href + '" style="color:#0a5ba8;text-decoration:none">' + esc(i.l) + '</a>' : '<span>' + esc(i.l) + '</span>') +
      '<span style="white-space:nowrap;' + (i.red ? 'color:#c62828;font-weight:600' : 'color:#4a5a66') + '">' + esc(i.r) + '</span></div>').join('')
    : '<div style="color:#6b7a85;font-size:14px;padding:8px 0">' + esc(empty) + '</div>';
  const note = t => '<div style="font-size:12px;color:#6b7a85;margin-top:8px">' + esc(t) + '</div>';
  const count = (rs, f) => rs.reduce((m, r) => (m[v(r, f)] = (m[v(r, f)] || 0) + 1, m), {});
  const rec = (t, id) => '/x/enno/gatenow-workspace/record/' + t + '/' + id;
  const s={}; rows('gn_reimb').forEach(r=>{const k=v(r,'status'); s[k]=(s[k]||0)+(parseFloat(v(r,'amount_requested'))||0);});
  const fmt=n=>'£'+Math.round(n).toLocaleString('en-GB');
  const order=[['Submitted','#378add'],['In review','#85b7eb'],['Approved','#185fa5'],['Paid','#0c447c'],['Rejected','#e24b4a']];
  return head('Reimbursement amounts')+bars(order.filter(o=>s[o[0]]!==undefined||['Submitted','Approved'].includes(o[0])).map(o=>({l:o[0],n:s[o[0]]||0,c:o[1]})),fmt)+note('Total amount requested');
}
